DO $$ BEGIN
  IF to_regclass('platform.tenants') IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM platform.tenants WHERE id <> '00000000-0000-0000-0000-000000000001') THEN
      RAISE EXCEPTION 'seed.sql chỉ dùng cho môi trường demo: phát hiện tenant khác, từ chối TRUNCATE dữ liệu của họ';
    END IF;
  END IF;
END $$;
